before('start HTTP server', (done) => {
    findOpenPortNumbers(1).then((ports) => {
      const express = require('express');
      const expressApp = express();

      backendServerPort = ports[0];

      expressApp.all('*', express.json(), express.urlencoded(), function (req, res) {
        if (req.header('r-test')) {
          res.setHeader('r-test', req.header('r-test'));
        }

        if (req.body) {
          should(req.body).have.property('hello', 'world');
        }

        res.setHeader('x-test', 'hello');
        res.status(200).json(Object.assign({ url: req.url }, req.body));
      });

      backendServer = expressApp.listen(backendServerPort, done);
    });
  })

before(() => {
    return serverHelper.findOpenPortNumbers(2)
      .then(([port, introspectionPort]) => {
        config.gatewayConfig = gatewayConfig(port, introspectionPort);
        const app = express();

        const returnToken = sinon
          .stub()
          .onFirstCall().callsFake(res => {
            res.json({ active: true });
          })
          .callsFake(res => {
            res.json({ active: true, scopes: 'read write' });
          });

        introspectEndpointSpy = sinon.spy((req, res) => {
          if (req.header('authorization') !== 'YXBpMTpzZWNyZXQ=') {
            return res.sendStatus(401);
          }

          if (!['token_value_1', 'token_value_2'].includes(req.body.token)) {
            return res.json({ active: false });
          }

          returnToken(res);
        });
        app.post('/introspect', express.urlencoded({ extended: true }), introspectEndpointSpy);
        return new Promise((resolve, reject) => {
          introspectApp = app.listen(introspectionPort, (err) => {
            if (err) return reject(err);
            resolve();
          });
        }).then(() => serverHelper.generateBackendServer(port));
      }).then(({ app }) => { backend = app; })
      .then(() => testHelper.setup()).then(({ app }) => { gateway = app; });
  })

before('start HTTP server', (done) => {
    findOpenPortNumbers(1).then((ports) => {
      const https = require('https');
      const express = require('express');
      const expressApp = express();

      backendServerPort = ports[0];

      expressApp.all('*', express.json(), function (req, res) {
        if (req.headers['x-test']) {
          res.setHeader('x-test', req.header('x-test'));
        }

        if (req.headers['x-forwarded-for']) {
          res.setHeader('x-forwarded-for', req.header('x-forwarded-for'));
        }

        res.status(200).json(Object.assign({ url: req.url }, req.body));
      });

      backendServer = https.createServer({
        key: fs.readFileSync(serverKeyFile),
        cert: fs.readFileSync(serverCertFile),
        ca: fs.readFileSync(chainFile),
        requestCert: true,
        rejectUnauthorized: true
      }, expressApp);

      backendServer.listen(backendServerPort, done);
    });
  })

