beforeEach(() => {
      maxId = 2;
      storage = {
        1: { id: "1", value: "test" },
        2: { id: "2", value: "other" },
      };

      Model = {
        id: true,
        value: "",
        [store.connect]: {
          get: id => storage[id],
          set: (id, values) => {
            if (!id) {
              maxId += 1;
              const result = { ...values, id: maxId };
              storage[id] = result;
              return result;
            }

            if (values) {
              storage[id || values.id] = values;
              return values;
            }

            delete storage[id];
            return null;
          },
          list: () => Object.keys(storage).map(key => storage[key]),
        },
      };
    })

