afterEach(async () => {
  if (driverPromise) {
    const { driver } = await driverPromise;

    try {
      global.__coverage__ = await driver.executeScript(() => window.__coverage__);

      ((await driver.executeScript(() => window.__console__)) || [])
        .filter(([type]) => type === 'error' && type === 'warn')
        .forEach(([type, message]) => {
          console.log(`${type}: ${message}`);
        });
    } finally {
      await driver.quit();
      driverPromise = null;
    }
  }
})

beforeEach(() => {
  const sagaMiddleware = createSagaMiddleware();

  store = createStore(
    ({ actionTypes = [] } = {}, { type }) =>
      /^DIRECT_LINE\/(DIS|RE)?CONNECT/u.test(type)
        ? // We are only interested in CONNECT_*, RECONNECT_*, and DISCONNECT_* actions.
          { actionTypes: [...actionTypes, type] }
        : { actionTypes },
    applyMiddleware(sagaMiddleware)
  );

  sagaMiddleware.run(connectSaga);

  directLine = {
    activity$: new Observable(() => () => 0),
    connectionStatus$: new Observable(observer => {
      connectionStatusObserver = observer;
      observer.next(0);
    }),
    end: () => 0,
    postActivity: () =>
      new Observable(observer => {
        observer.next({ id: '' });
      })
  };
})

