            iframe.style.cssText = style + ' green';
            break;
          case 'split-view':
            console.log(microFrontendType);
            iframe.style.cssText = style + ' red';
            break;
          case 'modal':
            console.log(microFrontendType);
            iframe.style.cssText = style + ' blue';
            break;
        }
      };
      win.Luigi.configChanged('settings.header');
    });
  })

