        var foo_interceptor = function (options, nextCall) {
          var outbound = (new RequesterBuilder())
            .withStart(function (metadata, listener, next) {
              metadata.add(keys.foo, values.foo);
              registry.addCall('foo');
              next(metadata, listener);
            }).build();
          return new InterceptingCall(nextCall(options), outbound);
        };
        var bar_interceptor = function (options, nextCall) {
          var outbound = (new RequesterBuilder())
            .withStart(function (metadata, listener, next) {
              metadata.add(keys.bar, values.bar);
              registry.addCall('bar');
              next(metadata, listener);
            }).build();
          return new InterceptingCall(nextCall(options), outbound);
        };
        options = { interceptors: [foo_interceptor, bar_interceptor] };
      })

before(function() {
        var foo_interceptor = function (options, nextCall) {
          var startNext;
          var startListener;
          var startMetadata;
          var methods = {
            start: function (metadata, listener, next) {
              startNext = next;
              startListener = listener;
              startMetadata = metadata;
            },
            sendMessage: function (message, next) {
              startMetadata.set('fromMessage', message.value);
              startNext(startMetadata, startListener);
              next(message);
            }
          };
          return new InterceptingCall(nextCall(options), methods);
        };
        options = { interceptors: [foo_interceptor] };
      })

before(function(done) {
        server = new serverGrpc.Server();
        var trailer_metadata = new serverGrpc.Metadata();
        trailer_metadata.add('trailer-present', 'yes');
        server.addService(TestServiceClient.service, {
          unary: function(call, cb) {
            var req = call.request;
            if (req.error) {
              var message = 'Requested error';
              if (req.message) {
                message = req.message;
              }
              cb({code: serverGrpc.status.UNKNOWN,
                  details: message}, null, trailer_metadata);
            } else {
              cb(null, {count: 1}, trailer_metadata);
            }
          },
          clientStream: function(stream, cb){
            var count = 0;
            var errored;
            stream.on('data', function(data) {
              if (data.error) {
                var message = 'Requested error';
                if (data.message) {
                  message = data.message;
                }
                errored = true;
                cb(new Error(message), null, trailer_metadata);
              } else {
                count += 1;
              }
            });
            stream.on('end', function() {
              if (!errored) {
                cb(null, {count: count}, trailer_metadata);
              }
            });
          },
          serverStream: function(stream) {
            var req = stream.request;
            if (req.error) {
              var message = 'Requested error';
              if (req.message) {
                message = req.message;
              }
              var err = {code: serverGrpc.status.UNKNOWN,
                        details: message};
              err.metadata = trailer_metadata;
              stream.emit('error', err);
            } else {
              for (var i = 0; i < 5; i++) {
                stream.write({count: i});
              }
              stream.end(trailer_metadata);
            }
          },
          bidiStream: function(stream) {
            var count = 0;
            stream.on('data', function(data) {
              if (data.error) {
                var message = 'Requested error';
                if (data.message) {
                  message = data.message;
                }
                var err = new Error(message);
                err.metadata = trailer_metadata.clone();
                err.metadata.add('count', '' + count);
                stream.emit('error', err);
              } else {
                stream.write({count: count});
                count += 1;
              }
            });
            stream.on('end', function() {
              stream.end(trailer_metadata);
            });
          }
        });
        server.bindAsync('localhost:0', serverInsecureCreds, (err, _port) => {
          assert.ifError(err);
          port = _port;
          client = new TestServiceClient('localhost:' + port, clientInsecureCreds);
          server.start();
          done();
        });
      })

